
const $=id=>document.getElementById(id); const n=id=>{const e=$(id); return e?Number(e.value):NaN};
function rnd(x,d=0){const p=10**d; return Math.round((Number(x)+Number.EPSILON)*p)/p}
function ibw(){const age=n('age'),sex=n('sex'),ht=n('ht');return rnd(age===1?(sex===1?50+0.91*(ht-152.4):45.5+0.91*(ht-152.4)):(ht>152.4?ht**2*1.65/1000:(sex===1?39+2.27*(ht/2.54-60):42+2.27*(ht/2.54-60))),1)}
function bmi(){return rnd(n('wt')/(n('ht')*.01)**2,1)}function bsa(){return rnd(.016667*Math.sqrt(n('wt'))*Math.sqrt(n('ht')),2)}function lbm(){return rnd(n('sex')===1?.407*n('wt')+.267*n('ht')-19.2:.252*n('wt')+.473*n('ht')-48.3,1)}
function tv5(){return rnd(5*ibw(),0)}function tv6(){return rnd(6*ibw(),0)}function tv7(){return rnd(7*ibw(),0)}function tv8(){return rnd(8*ibw(),0)}
function bmiClass(){const x=bmi();return x<18.5?'(Underweight)':x<25?'(Normal weight)':x<30?'(Overweight)':x<35?'(Obese Class 1)':x<40?'(Obese Class 2)':'(Obese Class 3)'}
function remi_c(){return rnd(1000*n('remi')/n('remi_t'),0)}function remiRate(x){return rnd(x*n('wt')*60/(1000*n('remi')/n('remi_t')),1)}function remi_0_08(){return remiRate(.08)}function remi_0_10(){return remiRate(.10)}function remi_0_15(){return remiRate(.15)}function remi_0_20(){return remiRate(.20)}function remi_0_25(){return remiRate(.25)}function remi_0_30(){return remiRate(.30)}function remi_0_35(){return remiRate(.35)}function remi_0_40(){return remiRate(.40)}function suf_c(){return rnd(n('suf')/n('suf_t'),0)}function alf_c(){return rnd(1000*n('alf')/n('alf_t'),0)}function fent_c(){return rnd(n('fent')/n('fent_t'),0)}function aminoph_c(){return rnd(n('aminoph')/n('aminoph_t'),0)}function lasx_c(){return rnd(n('lasx')/n('lasx_t'),0)}function temp_c(){return 0}
function out_ibw_text(){ return ["Ideal Body Weight: ",ibw()," Kg"].join(""); }
function out_bmi_text(){ return `Body Mass Index: ${bmi()} Kg/m<sup>2</sup>&nbsp;${bmiClass()}`; }
function out_bsa_text(){ return ["Body Surface Area: ",bsa()," m","<sup>2</sup>"].join(""); }
function out_lbm_text(){ return ["Lean Body Mass: ",lbm()," %"].join(""); }
function out_tv_text(){ return ["<br>","TV Setting","<br>","5 mL/Kg: ",tv5(),"mL","<br>","6 mL/Kg: ",tv6(),"mL","<br>","7 mL/Kg: ",tv7(),"mL","<br>","8 mL/Kg: ",tv8(),"mL","<br>","<br>","<i>Use PEEP more than 5 cmH2O when applying small TV to your patient!</i>","<br>","<br>"].join(""); }
