function out_lipid_text(){ return ["<b>Supply</b>: 20% IV lipid emulsion 100/500mL","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","SmofLipid 20% INJ 100/500mL (Fresenius Kabi)","<br>","<br>",["LBM:",lbm(),"% ",((n("sex") == 1) ? ("Male") : ("Female")),"<br>","<u>Initial</u>: ",((lbm()<70) ? (rnd(1.5*lbm(),0)) : ("100")),"mL for 2-3 min (use 50mL syringe by manual administration)","<br>","<u>Infusion</u>: Agilia pump with 50 mL syringe preferred (rate limit 1200mL/h) ",((lbm()<70) ? ([rnd(0.25*lbm()*15,0),"-",rnd(0.25*lbm()*20,0)].join(" ")) : ("200-250")),"mL for 15‒20min. (Infusion pump, ",4*(((lbm()<70) ? (rnd(0.25*lbm()*15,0)) : (200))),"-",4*(((lbm()<70) ? (rnd(0.25*lbm()*20,0)) : (250))),"mL/h for 15min or ",3*(((lbm()<70) ? (rnd(0.25*lbm()*15,0)) : (200))),"-",3*(((lbm()<70) ? (rnd(0.25*lbm()*20,0)) : (250))),"mL/hr for 20min.","<br>","If circulatory stability is not attaiend, <i>re-bolusing up to two futher infusion</i> or increasing the infusion to ",rnd(0.5*lbm()*15,0),"-",rnd(0.5*lbm()*20,0),"mL for 15‒20min.(",4*(rnd(0.5*lbm()*15,0)),"-",4*(rnd(0.5*lbm()*20,0)),"mL/h for 15min or ",3*(rnd(0.5*lbm()*15,0)),"-",3*(rnd(0.5*lbm()*20,0)),"mL/hr for 20min).","<br>","<br>","<br>","<br>"].join("")].join(""); }
function out_ddavp_text1(){ return ["<u>Definition</u>","<br>","Central DI: Insufficient ADH by the posterior pituitary","<br>","Nephrogenic DI: Failure of the renal tubules to respond to ADH","<br>","<br>","<u>Clinical suspicion</u>","<br>","<i>Central DI</i>","<br>","(High) Polyuria immediately after sellar/suprasellar region surgery.","<br>","(High) Polyuria immediately aftersevere head trauma.","<br>","(High) Polyuria immediately after basilar skull fracture.","<br>","Patients with brain tumors, sarcoidosis.","<br>","Brain death: Donor","<br>","Post LTx/Htx","<br>","Sevoflurane, Dexmedetomidine","<br>","&nbsp;","&nbsp;","<i>Anesthesia & Analgesia 134(1):p 82-89, January 2022.</i>","<br>","","<br>","","<br>","<i>Nephrogenic DI</i>","<br>","Diverse conditions as hypokalemia, hypercalcemia, sickle cell anemia, \n             obstructive uropathy,and renal insufficiency","<br>","","<br>","<u>Treatment</u>","<br>","Mild DI (UO of 2-4L/day (80-160mL/hr)): No Tx.","<br>","<b>Normal Saline</b> for fluid deficit, 2/3 of previous hour OU + maintanance (or previous HOU - 50mL + Maintenance),","<br>","<b>Half normal saline (with 5% Dextrose) </b> required once urine osm<290 mOsm/Kg or plasma osm > 300 mOsm/L","<br>","","<br>","<Water Deficit Calculation>","<br>"].join(""); }
function out_ddavp_text2(){ return ["<i>Water deficit (L) = 0.6*",n("bwt"),"*(",n("na"),"-140)/140 = <b>",rnd(0.6*n("bwt")*(n("na")-140)/140,0),"L</b></i>","<br>","<br>","<b>DDAVP</b>: Supplied as 100 ug/mL (intranasal) and 4 ug/mL (injection).\n             Often used when <u>fluid requirement more than 350-400 mL/h or UO > 250 mL/h.</u>.\n             Just before surgery, 0.4-1 ug SC or IV every 6-24hrs or 2.5-10 ug (0.025-0.1 mL) \n             intranasal, twice daily (duation, 10-11 hrs). 1/10 nasal dose SC or IV when nasal congestion. \n             (<i>Side effects</i>) <u>hyPOnatremia, HTN, coronary a vasospasm, oxytocic effect.</u>.","<br>","LTx/HTx donor: UO>300mL/h, treat promptly with desmopressin.","<br>","","<br>","<b>Vasopressin</b>: Prepare 1U/100mL diluted solution (10 mU/mL). \n             100mU IV (10 mL) followed by infusion of 100 - 200 mU/h (10-20 mL/h). \n             Consider rate increase over 200 mU/h when plasma osm over 300 mOsm/L. 0.02-0.2 U (0.1-1.0 mL) IM also available (duration, 4-6 h).\n             Adjusted to permit the daily breakthrough polyuria to prevents the iatrogenic syndrome of SIADH.\n             <u>Partial deficiency</u> not requires vasopressin until plasma osm > 300.","<br>","","<br>","<b>Nephrogenic DI</b> is associated with failure of vasopressin to reduce urinary volume.\n             Adequate oral or parenteral hydration must be assured.\n             <u>Chlorpropamide</u> (oral hypoglycemic) potentiates the effects of ADH on renal tubules\n             and may be helpful. Inhibition of prostaglandin synthesis (by \n             <u>ibuprofen, indomethacin, or aspirin</u>) or mild salt depletion with a <u>thiazide diuretic</u>\n             may reduce urine volume.","<br>","","<br>","","<br>"].join(""); }
function out_ddavp_text3(){ return ["Desmopressin increases circulating vWF and factor VIII.","<br>","","<br>","Regarding 2015 ASA PBM, Consider use of desmopressin in patients with excessive bleeding or suspected platelet dysfunction.","<br>","","<br>","<u>After CPB, Post HT Bleeding</u>: Especially for ThoracoAbdominal Aneurysm surgery. 0.3 ug/kg (",rnd(0.3*n("wt"),0),"ug) in 50mL NS, IV over 30 min.\n             Do not rely on desmopressin when Plasma factor VIII < 5%. Cautions for <u>hypotension</u> related to deacreased SVR.","<br>","","<br>","<u>LTx bleeding</u>: Not confirmed, there are several case report with successful hemostasis with desmopressin.","<br>","","<br>","<u>Renal Failure</u>: Abnormal bleeding times and coagulopathy in patients with renal failure may be managed with \n             desmopressin, cryoprecipitate, conjugated estrogens, blood transfusions, and erythropoietin use.","<br>","","<br>","<u>Type 1 & 2A vWF dz</u>: Desmopressin can be used, \n             <i>Not for type 2 or 3 vWF dz (Risk of thrombocytopenia for type 2B)</i>.\n             Intranasal first. Also possible IV 0.3 ug/kg (",rnd(0.3*n("wt"),0),"ug) in 50mL NS, over 30 min.","<br>","","<br>","<u>Osteogenesis Imperfecta</u>: Consider with preoperative coagulopathy and platelet dysfunction.","<br>","","<br>","","<br>"].join(""); }
function out_lasx_text(){ return ["<u>Supply</u>: 20mg/2mL ample (10mg/mL)","<br>","<br>",((n("age") == 1) ? (["--- Infusion (Adult) ---","<br>","Prep: ",n("lasx")," mg/ ",n("lasx_t")," mL 5DW (",lasx_c()," mg/mL)","<br>","20 mg/hr (0.33 mg/min): ",rnd(20/lasx_c(),1)," mL/hr","<br>","40 mg/hr (0.67 mg/min): ",rnd(40/lasx_c(),1)," mL/hr","<br>","60 mg/hr (0.99 mg/min): ",rnd(60/lasx_c(),1)," mL/hr","<br>","80 mg/hr (1.33 mg/min): ",rnd(80/lasx_c(),1)," mL/hr","<br>","100 mg/hr (1.67 mg/min): ",rnd(100/lasx_c(),1)," mL/hr","<br>","240 mg/hr (4 mg/min): ",rnd(240/lasx_c(),1)," mL/hr","<br>","A rate not exceeding 4 mg/min","<br>","<br>"].join("")) : (((n("age") == 2) ? (["---Bolus (Children) ---","<br>","0.1-1.0 mg/kg (",rnd(0.1*Number(n("wt")),1),"-",rnd(Number(n("wt")),1),"mg)","<br>","<br>"].join("")) : (""))))].join(""); }
function out_hyperk_text(){ return ["<b>Hyperkalemia severity</b>","<br>","Mild: <6 mEq/L","<br>","Moderate: 6-6.7 mEq/L","<br>","Severe: >6.5 mEq/L","<br>","<br>","Stop all exogenous K administration - including pRBC, Fluid","<br>"].join(""); }
function out_hypok_text(){ return ["A serum K<sup>+</sup> level of 2 mEq/L represents a deficit of about 300 mEq in a 70-kg adult.\n             To change K<sup>+</sup> from 3 to 4 mEq/L it takes about 100 mEq of K<sup>+</sup> in a 70-kg adult, \n             and from 2 to 3 mEq/L it may take up to 200 mEq.","<br>","","<br>","Treat hypomagnesemia if present (Mg<sup>+</sup> < 1.5 mEq/L). It is difficult to correct hypokalemia in \n             the presence of hypomagnesemia.","<br>","","<br>","<b>Rapid Correction</b>","<br>","Give KCl IV. Monitor heart rhythm with replacement > 20 mEq/hr.","<br>","IV K<sup>+</sup> can be painful and sclerose veins.","<br>","Patient <40 kg: 0.25 mEq/kg/hr × 2 hr","<br>","Patient >40 kg: 10–20 mEq/hr × 2 hr","<br>","Severe (<2 mEq/L): Maximum 40 mEq/hr IV in adults.","<br>","In all cases check a stat K<sup>+</sup> after each 2–4 hr of replacement.","<br>","","<br>"].join(""); }
function out_haldol_text(){ return ["<u>Actions</u>: blocks postsynaptic mesolimbic dopaminergic D1 and D2 receptors in the brain; \n             depresses the reticular activating system.","<br>","","<br>","<u>Indications</u>: treatment of psychosis, Tourette’s disorder, sedation for severely agitated\n             or delirious patients, postoperative antiemetic.","<br>","","<br>","<u>Supplied</u>: Haloperidol lactate 5mg/1mL ample","<br>","","<br>","<u>Coutions</u>: Geriatrics, Glaucoma, BPH, Seizure disorder.","<br>","","<br>","<u>Dose (adult)</u>:","<br>","<i>Agitation/Delirium</i>: 2-5 mg <u>IM</u> every 4-8 hrs as needed (Not IV).","<br>","<i>Antiemetic</i>: 0.01 mg/kg/dose IV every 8-12 hrs.","<br>","<i>ICU sedation</i>: mild agitation: 0.5-2 mg IV/IM; moderate agitation: \n             2-5 mg IV/IM; severe agitation: 10-20 mg IV/IM; continuous infusion: \n             1-40 mg/hr (100 mg/100 mL D5W).","<br>","","<br>","<u>PKPD</u>:","<br>","Onset: IM, 10-30 min.","<br>","Peak effect: Im, 30-45 min.","<br>","Duration of action: 12-38 hours (half-life).","<br>","Elimination: Hepatic","<br>","","<br>","<u>Adverse effects</u>: may cause extrapyramidal reactions or mild alpha-adrenergic antagonism; \n             can prolong QT interval and produce ventricular arrhythmias, notably torsade de pointes; \n             can lower seizure threshold; may precipitate neuroleptic syndrome.","<br>","","<br>","<u>Comments</u>: Use caution in cardiac disease due to adverse reactions such as tachycardia, hyper/hypotension.","<br>","When hypotension, use pheylephrine or norepinephrine, not epinephrine (paradoxical hypotension).","<br>","","<br>","","<br>","","<br>","","<br>","","<br>","","<br>"].join(""); }
function out_acupan_text(){ return ["<u>Supplied</u>: 10 mg / 1 mL, 2mL ample","<br>","","<br>","<u>Dosing</u>: 20 mg IM,IV (for 15min) in every 6hrs, upto 120 mg/day.","<br>","","<br>","<u>C/Ix</u>:","<br>","Pregnancy","<br>","Epilepsy","<br>","MI","<br>","MAO inhibitor","<br>","age < 15 yrs","<br>","Seizure Hx","<br>","Urinary retension","<br>","IIOP (obstructive glaucoma)","<br>","","<br>","<u>Side effect</u>: Nausea/Vomiting, diaphoresis, dizziness, tachycardia, thirsty, urinary retension,\n             asymptomatic pinkish urine. (Sometimes) headache, restless.","<br>","","<br>","<u>Cautions</u>: Injection pain, maybe related to venous sclerosis.","<br>","","<br>","","<br>"].join(""); }
function out_hyperglc_text(){ return ["Every 1U RI reduces plasma glucose by 50(30-100) mg/dL.","<br>","","<br>","DO NOT begin insulin if K<sup>+</sup> is <3.3 mg/dL (0.84 mEq/L), \n                          begin insulin when K<sup>+</sup> is >3.3 mg/dL","<br>","","<br>","<b>GIK infusion protocol</b>","<br>","<u>5% dextrose (5DW, 5DS) 1L + RI 15U + KCL 20 mEq</u>","<br>","","<br>","<u>RI: 0.3U per 1g of dextrose</u> ","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","Plasma Glc < 80 mg/dL: decrease 5U","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","Plasma Glc < 120 mg/dL: decrease 3U","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","Plasma Glc 120-180 mg/dL: No adjustment","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","Plasma Glc 181-270 mg/dL: increase 3U","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","Plasma Glc >270 mg/dL: Increase 5U","<br>","","<br>","<u>K<sup>+</sup>: 20 mEq per 1L</u>","<br>","&nbsp;","&nbsp;","&nbsp;","&nbsp;","CRF, Hyperkalemia: Without potassium","<br>","","<br>","<u>Infusion rate</u>: 80-125 mL/h","<br>","<u>Target</u>: Plasma glucose 120-180 mg/dL","<br>","<u>Monitoring</u>: Plasma glucose in every 1h","<br>","","<br>","<b>Piggyback method</b>","<br>","<u>Preparation</u>","<br>","&nbsp;","&nbsp;","RI: 0.9%NS 250mL+RI 25U (0.1U/mL)","<br>","&nbsp;","&nbsp;","50% dextrose solution 100mL","<br>","","<br>","<u>Infusion rate</u>","<br>","&nbsp;","&nbsp;","RI: 10 mL/h (1 U/h)","<br>","&nbsp;","&nbsp;","50% dextrose: 10mL/h","<br>","","<br>","<u>Monitoring</u>: Plasma glucose in every 1h","<br>","","<br>","<u>Adjustment: RI infusion rate</u>","<br>","&nbsp;","&nbsp;","Glc < 80 mg/dL: Stop RI, check Glc in 15 min","<br>","&nbsp;","&nbsp;","Glc 80-140: Decrease 0.4 U/h (4 mL/h)","<br>","&nbsp;","&nbsp;","Glc 141-180: Maintain","<br>","&nbsp;","&nbsp;","Glc 181-220: Increase 0.4 U/h (4 mL/h)","<br>","&nbsp;","&nbsp;","Glc 221-250: Increase 0.6 U/h (6 mL/h)","<br>","&nbsp;","&nbsp;","Glc 251-300: Increase 0.8 U/h (8 mL/h)","<br>","&nbsp;","&nbsp;","Glc >300: Increase 1.0 U/h (10 mL/h)","<br>","","<br>","<u>Cautions</u>","<br>","Blocked insulin lines can lead to hyperglycemia, \n             while blocked glucose fluid lines can cause serious hypoglycemia. \n             Constant vigilance is essential.","<br>","","<br>"].join(""); }
function out_larynx_text(){ return ["TBD, will included epinephrine nebulization","<br>","","<br>"].join(""); }
function out_siadh_text(){ return ["SIADH should be suspected in any patient with hyponatremia who excretes urine that is hypertonic relative to plasma.","<br>","<u>Support the diagnosis:</u>","<br>","<i>1. Urinary sodium greater than 20 mEq/L","<br>","2. Low serum levels of BUN, creatinine, uric acid, and albumin","<br>","3. Serum sodium lower than 130 mEq/L","<br>","4. Plasma osmolality lower than 270 mOsm/L","<br>","5. Urine osmolality greater than serum osmolality (with a low serum osmolality)</i>","<br>","in malignancy, CNS disorders (trauma, infection, and tumor), pulmonary disorders \n             (tuberculosis, pneumonia, positivepressure ventilation, and chronic obstructive pulmonary disease), \n             and drugs (nicotine, narcotics, chlorpropamide, clofibrate, vincristine, vinblastine, cyclophosphamide, \n             and serotonin reuptake inhibitors). Other etiologies include lupus, HIV, Guillain-Barre, hypothyroidism, \n             Addison disease, congestive heart failure, cirrhosis, and porphyria. ","<br>","","<br>","No drugs are available that can suppress release of ADH.","<br>","Demethylchlortetracycline 900 to 1200 mg/day PO: Interferes with the ability of the renal tubules to concentrate urine, lessening the hyponatremia.","<br>","","<br>","For <u>surgical patient</u>, fluid are managed by measuring volume status:","<br>","- Arterial wave form analysis","<br>","- CVP, PCWP","<br>","- TTE/TEE","<br>","","<br>","Mostly requires <b>fluid restriction</b> only, rarely needs hypertonic saline.","<br>","Serum sodium < 110 mEq/L, risk of cerebral edema and seizures.","<br>","","<br>","Fluid restriction (800 to 1,000 mL daily) for the mild hyponatremia.","<br>","<u>Symptomatic, severe hyponatremia</u> (serum Na <120 mEq/L): <b>Do not correct faster than \n             0.5 mEq Na/L/h</b>, due to <i>osmotic demyelination syndrome</i>.","<br>","Demeclocycline antagonizes the effects of ADH on renal tubules and may be helpful.","<br>","","<br>","","<br>"].join(""); }
