function renderAll(){
  const outputs=["ibw_text", "bmi_text", "bsa_text", "lbm_text", "tv_text", "inform_ref", "abga1_text", "abga2_text", "adenosine_text", "amio_text", "herben_text", "dobu_text", "dopa_text", "epi_text", "esmolol_text", "isuprel_text", "isoket_text", "lido_text", "mb_text", "mil_text", "ntg_text", "ntp_text", "ne_text", "phe_text", "vaso_text", "vera_text", "dex_4text", "acupan_text", "remima_text", "alf_text", "fent_text", "suf_text", "remi_text", "aminoph_text", "anaphyl_text", "asthma_text", "bronchospasm_text", "dantrol_text", "ddavp_text1", "ddavp_text2", "ddavp_text3", "lasx_text", "haldol_text", "hyperc_text", "hyperglc_text", "hyperk_text", "hyperm_text", "hyperp_text", "hypoc_text", "hypok_text", "hypom_text", "hypop_text", "larynx_text", "lipid_text", "siadh_text"];
  for(const id of outputs){const fn=window['out_'+id]; const el=$(id); if(fn&&el){try{el.innerHTML=fn()}catch(e){el.innerHTML='<span style="color:#b42318">Calculation error: '+e.message+'</span>'}}}
  const r=$('remi_text'); if(r&&!r.querySelector('table')) r.insertAdjacentHTML('beforeend',"<table><thead><tr><th>Infusion rate (ug/kg/min)</th><th>TIVA (Cpt, ng/mL)</th><th>Target</th></tr></thead><tbody><tr><td>0.05</td><td>1.3</td><td>Sedation/awakening</td></tr><tr><td>0.1</td><td>2</td><td>Perioperatively, light pain</td></tr><tr><td>0.2</td><td>3</td><td>Surgical anesthesia</td></tr><tr><td>0.25</td><td>6</td><td>intubation</td></tr><tr><td>0.35</td><td>7.5</td><td>Strong pain stimuli</td></tr><tr><td>0.5</td><td>10</td><td>Deep Anesthesia</td></tr><tr><td>0.8</td><td>12</td><td>Very deep anesthesia</td></tr></tbody></table>");
  const a=$('dex_4text');
}
